vec3 f = (center - eye).normalized();

// Compute right vector (normalized)
vec3 r = (up.cross(f)).normalized();

// Compute actual up vector (normalized)
vec3 u = (f.cross(r)).normalized();

// Construct the view matrix
mat4 view;
view[0] = vec4(r.x, r.y, r.z, 0.0);
view[1] = vec4(u.x, u.y, u.z, 0.0);
view[2] = vec4(-f.x, -f.y, -f.z, 0.0);
view[3] = vec4(0.0, 0.0, 0.0, 1.0);

// Translate the camera to the origin
view = view * mat4::translate(-eye.x, -eye.y, -eye.z);

return view;

